def _wait_for_file(path, timeout=10.0):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if os.path.exists(path):
            return True
        time.sleep(0.05)
    return False

def test_r9_script_receives_predefined_arguments(tmp_path):
    out = tmp_path / "args.txt"
    script = _write_script(
        tmp_path,
        "echo_args.py",
        "import sys\n"
        "open({!r}, 'w').write('|'.join(sys.argv[1:]))\n".format(str(out)),
    )
    task_func(script, True, "alpha", "beta")
    assert _wait_for_file(str(out))
    assert out.read_text() == "alpha|beta"

def _write_script(tmp_path, name, body):
    path = tmp_path / name
    path.write_text(body)
    return str(path)

def _wait_for_file(path, timeout=10.0):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if os.path.exists(path):
            return True
        time.sleep(0.05)
    return False

def test_r10_script_runs_in_separate_process(tmp_path):
    out = tmp_path / "pid.txt"
    script = _write_script(
        tmp_path,
        "pid.py",
        "import os\n"
        "open({!r}, 'w').write(str(os.getpid()))\n".format(str(out)),
    )
    task_func(script)
    assert _wait_for_file(str(out))
    assert int(out.read_text()) != os.getpid()
